mapper.update:
UPDATE case_activity SET deleted = 1, updated_at = #{now}, calculated_at = #{now} WHERE id IN
#{id}
AND deleted = 0

mapper.select:
SELECT ca.id, ca.case_id, ac.name AS case_name, ac.application_id, app.name AS application_name, ca.last_debug_time, ca.last_flow_execute_time, ca.last_suite_execute_time, ca.last_view_time, GREATEST( COALESCE(ca.last_debug_time, '1970-01-01'), COALESCE(ca.last_flow_execute_time, '1970-01-01'), COALESCE(ca.last_suite_execute_time, '1970-01-01'), COALESCE(ca.last_view_time, '1970-01-01') ) AS last_active_time, ca.calculated_at, ca.created_at, ca.updated_at FROM case_activity ca LEFT JOIN api_case ac ON ca.case_id = ac.id AND ac.deleted = 0 LEFT JOIN application app ON ac.application_id = app.id AND app.deleted = 0 WHERE ca.deleted = 0
AND ac.application_id = #{applicationId}
AND GREATEST( COALESCE(ca.last_debug_time, '1970-01-01'), COALESCE(ca.last_flow_execute_time, '1970-01-01'), COALESCE(ca.last_suite_execute_time, '1970-01-01'), COALESCE(ca.last_view_time, '1970-01-01') ) >= #{threshold}
AND GREATEST( COALESCE(ca.last_debug_time, '1970-01-01'), COALESCE(ca.last_flow_execute_time, '1970-01-01'), COALESCE(ca.last_suite_execute_time, '1970-01-01'), COALESCE(ca.last_view_time, '1970-01-01') ) < #{threshold}
ORDER BY last_active_time DESC
